import {Converter} from './opencc.js';
                                                      
                                                                                                                                                                                                           
export const fields={artist:'画师',cv:'声优',class:'职阶',alignment:'属性',sub:'副属性',gender:'性别',np:'宝具',region:'地域',origin:'出处',cn:'国服实装',cards:'配卡',acquisition:'获取途径'};
export const keys=(hard=false)=>Object.keys(fields).filter(k=>!hard||!['gender','np','region','cn'].includes(k));
export const missing=(v    )        =>v==null||v===''||Array.isArray(v)&&(!v.length||v.some(missing));
const norm=(v    )       =>String(v).normalize('NFKC').trim();
export function compare(k       ,a    ,b    )        {if(missing(a)||missing(b))return 'unknown';if(k==='cards'){a=a.replace(/\s/g,'').toUpperCase();b=b.replace(/\s/g,'').toUpperCase();if(!/^[BAQ]{5}$/.test(a)||!/^[BAQ]{5}$/.test(b))return 'unknown';a=a.split('').sort().join('');b=b.split('').sort().join('');}
if(k==='alignment')return a.every((v    ,i       )=>norm(v)===norm(b[i]))?'exact':a.some((v    ,i       )=>norm(v)===norm(b[i]))?'partial':'miss';
if(Array.isArray(a)&&Array.isArray(b)){const canon=(arr      )=>[...new Set(arr.map(v=>Array.isArray(v)?JSON.stringify(v.map(norm)):norm(v)))].sort();const aa=canon(a),bb=canon(b);if(JSON.stringify(aa)===JSON.stringify(bb))return 'exact';if(aa.some(v=>bb.includes(v)))return 'partial';if(k==='region'){const parts=(items         )=>items.flatMap(v=>v.split(/[·・]/)).map(norm);if(parts(a).some(v=>parts(b).includes(v)))return 'partial';}if(k==='np'&&a.some((x    )=>b.some((y    )=>x[0]===y[0]||x[1]===y[1])))return 'partial';return 'miss';}return a===b?'exact':'miss';}
export const day=(d=new Date())=>new Date(+d+28800000).toISOString().slice(0,10);
export function hash(text       ){let h=2166136261;for(const c of text)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0;}
export function daily(pool      ,date=day(),version='v1'){if(!pool.length)throw Error('答案池为空');return pool[hash(version+date)%pool.length];}
export function randomAnswer(pool          ,previous        ,random=Math.random){const choices=pool.filter(x=>x.id!==previous);if(!choices.length)throw Error('可用答案不足');return choices[Math.floor(random()*choices.length)];}
export function submit(s    ,id       ,validIds             ){if(validIds&&!validIds.has(id)||s.guesses.includes(id)||s.guesses.length>=8||s.guesses.includes(s.answer))return s;return {...s,guesses:[...s.guesses,id]};}
export function restore(raw            ,db          ,expected        ){try{const s=JSON.parse(raw||'null');const ids=new Set(db.map(x=>x.id));if(!s||!ids.has(s.answer)||expected&&s.answer!==expected||!Array.isArray(s.guesses)||s.guesses.length>8||new Set(s.guesses).size!==s.guesses.length||s.guesses.some((x    )=>!ids.has(x))||s.guesses.includes(s.answer)&&s.guesses.at(-1)!==s.answer)return null;return s;}catch{return null;}}
const toSimple=Converter({from:'tw',to:'cn'});
export const normalize=(s       )=>toSimple(s.normalize('NFKC')).toLowerCase().replace(/[\s·・〔〕\[\]（）()－—\-／/]/g,'');
export function distance(a       ,b       ){if(Math.abs(a.length-b.length)>2)return 99;let row=Array.from({length:b.length+1},(_,i)=>i);for(let i=0;i<a.length;i++){let next=[i+1];for(let j=0;j<b.length;j++)next[j+1]=Math.min(next[j]+1,row[j+1]+1,row[j]+(a[i]===b[j]?0:1));row=next;}return row[b.length];}
const cache=new WeakMap              ();
export function search(db          ,query       ){const q=normalize(query);if(!q)return [];let index=cache.get(db);if(!index){index=db.map(s=>({s,n:normalize(s.name),alias:s.aliases.map(normalize),other:[s.jp,s.en,s.displayName].filter(Boolean).map(normalize),py:(s.pinyin||[]).join('').replace(/\s/g,''),initial:(s.pinyin||[]).map(p=>p[0]).join('')}));cache.set(db,index);}
const ranked=index.map(({s,n,alias,other,py,initial})=>{let rank=n===q?0:alias.includes(q)?1:other.includes(q)?2:n.startsWith(q)?3:alias.some((a       )=>a.startsWith(q))?4:n.includes(q)||alias.some((a       )=>a.includes(q))?5:/^[a-z]+$/.test(q)&&q.length>1&&(py.startsWith(q)||initial.startsWith(q))?6:other.some((a       )=>a.includes(q))&&q.length>1?6:q.length>=3&&[n,py,...other,...alias].some(a=>(distance(a,q)<=(q.length>6?2:1)||q.length>=4&&distance(a.slice(0,q.length),q)<=1))?7:99;return {s,rank};});const groups=new Set(ranked.filter(x=>x.rank<5&&x.s.group).map(x=>x.s.group));for(const r of ranked)if(r.rank===99&&groups.has(r.s.group))r.rank=8;return ranked.filter(x=>x.rank<99).sort((a,b)=>a.rank-b.rank||Number(a.s.id)-Number(b.s.id)).slice(0,30).map(x=>({...x.s,matchReason:x.rank===8?'关联版本':x.rank===7?'近似拼写':x.rank===6?'拼音 / 外文':''}));}
export function share(s    ,db          ,hard        ,label       ){const target=db.find(x=>x.id===s.answer) ;return `玛一把 ${label} ${hard?'困难':'简单'} ${s.guesses.includes(s.answer)?s.guesses.length:'X'}/8\n`+s.guesses.map((id       )=>keys(hard).map(k=>({exact:'🟩',partial:'🟨',miss:'⬜',unknown:'❔'})[compare(k,db.find(x=>x.id===id) [k],target[k])]).join('')).join('\n');}
